	public static AnimationDefinition of(EmperorAnim anim) {
		return switch (anim) {
			case IDLE -> IDLE;
			case DORMANT -> DORMANT;
			case SLAM_RIGHT -> SLAM_RIGHT;
			case SLAM_LEFT -> SLAM_LEFT;
			case BITE -> BITE;
			case BITE_RIGHT -> BITE_RIGHT;
			case BITE_LEFT -> BITE_LEFT;
			case WINGBEAT -> WINGBEAT;
			case WEEP -> WEEP;
			case REVEAL -> REVEAL;
			case HURT -> HURT;
			case DEATH -> DEATH;
		};
	}

	/** Every animation, in EmperorAnim's order. */
	public static List<AnimationDefinition> all() {
		return Arrays.stream(EmperorAnim.values()).map(EmperorAnimations::of).toList();
	}
